// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Find Vendor Outstanding Balance (Engineer - Production)
// Hand edits: text/id-based selectors instead of positions, state assertions, result screenshots,
// wide viewport, login fallback. READ-ONLY: this tour never creates or changes any record.
import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-find-vendor-outstanding-balance-engineer-production";
const VENDOR = "Engineer - Production";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Finance: Find Vendor Outstanding Balance (Engineer - Production) @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Find Vendor Outstanding Balance (Engineer - Production)", async ({ page }) => {
    test.setTimeout(180_000);
    // The vendor belongs to company "Jinasena (Pvt) Ltd." (id 1); the saved session opens on another company,
    // where the vendor is invisible. Select company 1 before loading Odoo.
    await page.context().addCookies([{ name: "cids", value: "1", url: process.env.ODOO_BASE_URL ?? "http://localhost:8069" }]);
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    // Shared step runner: wait for the target, take the outlined screenshot, act, optionally keep a result shot.
    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const menu = (xmlid: string) => page.locator(`[data-menu-xmlid="${xmlid}"]`);
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const dropItem = (name: string | RegExp) => page.locator(".dropdown-menu .dropdown-item").filter({ hasText: name });
    const search = async (l: Locator) => {
      // The vendor list opens with a default "Vendor Bills" filter that hides vendors without bills — drop it first.
      const dflt = page.locator(".o_searchview_facet").filter({ hasText: "Vendor Bills" });
      if (await dflt.first().isVisible().catch(() => false)) {
        await dflt.first().locator(".o_facet_remove").click();
        await expect(dflt).toHaveCount(0);
      }
      await l.fill(VENDOR);
      await l.press("Enter");
      await expect(page.locator(".o_searchview"), "vendor filter applied").toContainText(VENDOR, { timeout: 30000 });
    };

    await run(1, "Open Accounting app", menu("account_accountant.menu_accounting"), (l) => l.click());
    await run(2, "Open the Vendors menu", topMenu("Vendors"), async (l) => {
      await l.click();
      await expect(dropItem(/^Vendors$/).first()).toBeVisible();
    }, true);
    await run(3, "Open Vendors master list", dropItem(/^Vendors$/), async (l) => {
      await l.click();
      await expect(page.locator(".o_kanban_view, .o_list_view").first(), "vendor master opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(4, "Search the vendor", page.locator("input.o_searchview_input"), async (l) => {
      await search(l);
      await expect(page.locator(".o_kanban_record, .o_data_row").filter({ hasText: VENDOR }).first(), "vendor in the results").toBeVisible({ timeout: 30000 });
    }, true);
    await run(5, "Open the vendor record", page.locator(".o_kanban_record, .o_data_row").filter({ hasText: VENDOR }), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "vendor record opened").toBeVisible({ timeout: 30000 });
    }, true);
    // The "Due" smart button only appears for a vendor we still owe money to. This vendor may have a nil balance,
    // in which case the button is absent: the step then just shows the smart-button row and nothing is clicked.
    let hasDue = false;
    await run(6, "Open the More smart buttons", page.locator("button.o_button_more"), async (l) => {
      await l.click();
      await expect(page.locator("#partner_ledger_button"), "Partner Ledger button").toBeVisible({ timeout: 15000 });
      hasDue = await page.locator("button[name='open_action_followup']").first().isVisible().catch(() => false);
    }, true);
    await test.step("07. Read the Due amount", async () => {
      const box = page.locator("button.oe_stat_button").filter({ hasText: /Invoiced/ }).first();
      if (hasDue) {
        const due = page.locator("button[name='open_action_followup']").first();
        await shot(page, due, "step-07.png");
        await due.click();
        await expect(page.locator(".o_content"), "follow-up shows the total due").toContainText(/Total Due|Due/i, { timeout: 30000 });
      } else {
        await shot(page, box, "step-07.png");
      }
      await resultShot(page, 7);
    });
    await test.step("08. Back to the vendor record", async () => {
      const back = page.locator(".o_back_button, .breadcrumb-item").filter({ hasText: VENDOR }).first();
      if (hasDue) {
        await shot(page, back, "step-08.png");
        await back.click();
        await expect(page.locator("button.o_button_more"), "back on the vendor record").toBeVisible({ timeout: 30000 });
      } else {
        await shot(page, page.locator(".o_breadcrumb").first(), "step-08.png");
      }
      await resultShot(page, 8);
    });
    await test.step("09. Open More again", async () => {
      const more = page.locator("button.o_button_more").first();
      await shot(page, more, "step-09.png");
      if (!(await page.locator("#partner_ledger_button").isVisible().catch(() => false))) await more.click();
      await expect(page.locator("#partner_ledger_button"), "Partner Ledger button").toBeVisible({ timeout: 15000 });
      await resultShot(page, 9);
    });
    await run(10, "Open the Partner Ledger", page.locator("#partner_ledger_button"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Partner Ledger list opened").toBeVisible({ timeout: 30000 });
      await expect(page.locator(".o_searchview_facet").first(), "ledger filtered to the vendor").toBeVisible({ timeout: 30000 });
    }, true);
    await test.step("11. Read the Partner Ledger total", async () => {
      // The Debit / Credit totals sit in the footer row of the list.
      const total = page.locator("tfoot tr").first();
      await total.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, total, "step-11.png");
      await expect(page.locator("thead"), "Debit and Credit columns").toContainText(/Debit/);
      await expect(page.locator("thead")).toContainText(/Credit/);
    });
    await run(12, "Open the Reporting menu", menu("account.menu_finance_reports"), async (l) => {
      await l.click();
    }, true);
    await run(13, "Open Aged Payable", menu("account_reports.menu_action_account_report_aged_payable"), async (l) => {
      await l.click();
      await expect(page, "Aged Payable opened").toHaveTitle(/Aged Payable/);
      await page.locator("table tbody tr").first().waitFor({ state: "visible", timeout: 30000 });
    }, true);
    await test.step("14. Read the vendor row", async () => {
      // A vendor whose balance is nil does not appear in the ageing report, so fall back to the report total.
      const row = page.locator("tr.line_level_2").filter({ hasText: /Engineer\s*-\s*Production/i }).first();
      const found = await row.isVisible({ timeout: 10000 }).catch(() => false);
      const target = found ? row : page.locator("tr.line_level_0, tr.total").first();
      await target.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, target, "step-14.png");
      if (found) await expect(row).toContainText(/\d/);
      await resultShot(page, 14);
    });
    await run(15, "Back to the Vendors menu", topMenu("Vendors"), async (l) => {
      await l.click();
      await expect(dropItem(/^Bills$/).first()).toBeVisible();
    }, true);
    await run(16, "Open Vendor Bills", dropItem(/^Bills$/), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "vendor bills list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(17, "Filter bills by vendor", page.locator("input.o_searchview_input"), async (l) => {
      await search(l);
      await resultShot(page, 17);
    });
    await run(18, "Check the bills behind the balance", page.locator("thead th").filter({ hasText: /Status|Payment/ }), async () => {
      // The vendor may have no open bills — the list can legitimately be empty, so only the layout is checked.
      await expect(page.locator("thead"), "bill columns").toContainText(/Status/);
    }, true);
  });
});
